children.nodeValue:
*{transition:none!important;animation:none!important;box-sizing:border-box}
html,body{margin:0;padding:0;font:14px/1.4 monospace;background:#fff;color:#000}
main{padding:12px}
#scroller{width:420px;height:180px;overflow-y:scroll;border:1px solid #333}
#scroller .row{height:70px;border-bottom:1px solid #ddd;padding:4px}
#auto-scroller{width:420px;height:120px;overflow:auto;border:1px dashed #666;margin-top:12px}
#hidden-overflow{width:420px;height:80px;overflow:hidden;border:1px dotted #999;margin-top:12px}
#hidden-overflow .row{height:60px}

